	}
	if (
		!endpoint &&
		HEVY_ENDPOINT_TEMPLATES.includes(candidate as HevyEndpointTemplate)
	) {
		endpoint = candidate as HevyEndpointTemplate;
	}
	return endpoint
		? {
				known: true,
				canonical: endpoint,
				diagnostic: endpoint,
				metric: endpoint,
			}
		: {
				known: false,
				canonical: "unknown",
				diagnostic: undefined,
				metric: "unknown",
			};
}

